// ============================================================
// Starling AI — FUB Embedded App: verify FUB signature + route
// ============================================================
// 1) FUB app secret (Admin > Integrations > Embedded Apps > Starling AI > Secret Key)
const SECRET = '88619c984a861885e84b5e76d63ab3dc';

// 2) Which FUB accounts are Starling clients.
//    Key = the FUB account subdomain (the part before .followupboss.com).
//    To add a client: copy a line, change the subdomain + their table names + plan limit.
const CLIENTS = {
  'jasonhoustonrealty': { name: 'Jason Aguirre Group', chat_table: 'n8n_chat_histories', count_table: 'count_jasonaguirre', monthly_limit: 3000 },
};

// ---------- pure-JS SHA-256 / HMAC (no modules needed) ----------
function sha256Bytes(bytes) {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = bytes.length, withPad = ((l + 9 + 63) >> 6) << 6;
  const m = new Uint8Array(withPad); m.set(bytes); m[l] = 0x80;
  const bitLen = l * 8; const dv = new DataView(m.buffer);
  dv.setUint32(withPad - 4, bitLen >>> 0); dv.setUint32(withPad - 8, Math.floor(bitLen / 0x100000000));
  const w = new Uint32Array(64); const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let i = 0; i < withPad; i += 64) {
    for (let t = 0; t < 16; t++) w[t] = dv.getUint32(i + t * 4);
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t-15],7) ^ rotr(w[t-15],18) ^ (w[t-15] >>> 3);
      const s1 = rotr(w[t-2],17) ^ rotr(w[t-2],19) ^ (w[t-2] >>> 10);
      w[t] = (w[t-16] + s0 + w[t-7] + s1) >>> 0;
    }
    let [a,b,c,d,e,f,g,h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25), ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + w[t]) >>> 0;
      const S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22), mj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + mj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H = [H[0]+a,H[1]+b,H[2]+c,H[3]+d,H[4]+e,H[5]+f,H[6]+g,H[7]+h].map(x => x >>> 0);
  }
  const out = new Uint8Array(32); const odv = new DataView(out.buffer);
  H.forEach((x, i) => odv.setUint32(i * 4, x)); return out;
}
function utf8(s) { return new TextEncoder().encode(s); }
function hmacSha256Hex(key, msg) {
  let k = utf8(key); if (k.length > 64) k = sha256Bytes(k);
  const kp = new Uint8Array(64); kp.set(k);
  const ip = kp.map(b => b ^ 0x36), op = kp.map(b => b ^ 0x5c), mb = utf8(msg);
  const inner = new Uint8Array(64 + mb.length); inner.set(ip); inner.set(mb, 64);
  const ih = sha256Bytes(inner);
  const outer = new Uint8Array(96); outer.set(op); outer.set(ih, 64);
  return Array.from(sha256Bytes(outer)).map(b => b.toString(16).padStart(2, '0')).join('');
}
function safeEqual(a, b) {
  if (a.length !== b.length) return false;
  let r = 0; for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i); return r === 0;
}
function b64urlDecode(s) {
  let t = String(s).replace(/-/g, '+').replace(/_/g, '/').replace(/\s/g, '');
  while (t.length % 4) t += '=';
  const bin = atob(t); const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder().decode(bytes);
}

// ---------- mock data for FUB's review previews ----------
function mock(state) {
  const now = Date.now(), m = (min) => new Date(now - min * 60000).toISOString();
  if (state === 'working') return {
    state: 'working', client_name: 'Demo Realty', lead_first_name: 'Melissa', status: 'meeting_booked', last_activity: m(4),
    messages: [
      { from: 'ai', text: 'Hi Melissa! This is Avery with Demo Realty. I saw you were looking at homes in Katy. Are you hoping to buy in the next few months?', at: m(42) },
      { from: 'lead', text: 'Yes! Ideally by spring. 3 bedrooms, under 350k', at: m(31) },
      { from: 'ai', text: 'Great timing. Have you had a chance to get pre-approved yet, or would it help to talk with a lender first?', at: m(30) },
      { from: 'lead', text: 'Not yet. Can we talk tomorrow?', at: m(12) },
      { from: 'ai', text: 'Absolutely. I have 10:00 AM or 2:30 PM tomorrow. Which works better?', at: m(11) },
      { from: 'lead', text: '2:30 works', at: m(5) },
      { from: 'meeting', text: 'Call booked for tomorrow at 2:30 PM', at: m(4) },
    ],
    usage: { used: 1284, limit: 3000 },
  };
  if (state === 'account_not_found') return { state: 'account_not_found', account_id: 123456789, prefill: { name: 'Louis Tully', email: '' },
                                               preview: { lead_first_name: 'Melissa', agent_first_name: 'Louis' } };
  if (state === 'user_not_found') return { state: 'user_not_found' };
  if (state === 'person_not_found') return { state: 'person_not_found', usage: { used: 1284, limit: 3000 } };
  if (state === 'unauthorized') return { state: 'unauthorized' };
  return { state: 'working_unknown_debug', note: String(state) };
}

// ---------- main ----------
const body = ($input.first().json || {}).body || {};
const context = String(body.context || '');
const signature = String(body.signature || '').trim().toLowerCase();
const respond = (status, response) => [{ json: { route: 'respond', status, response } }];

if (!context || !signature) return respond(401, { state: 'invalid' });
if (!safeEqual(hmacSha256Hex(SECRET, context), signature)) return respond(401, { state: 'invalid' });

let ctx;
try { ctx = JSON.parse(b64urlDecode(context)); } catch (e) { return respond(400, { state: 'invalid' }); }

if (ctx.example === true) return respond(200, mock(String(ctx.debugState || 'working')));

const domain = String((ctx.account && ctx.account.domain) || '').toLowerCase();
const client = CLIENTS[domain] || CLIENTS[String((ctx.account && ctx.account.id) || '')];
if (!client) {
  // Not a Starling client yet -> show the pitch, and remember this FUB account as a lead.
  const acct = ctx.account || {}, owner = acct.owner || {}, user = ctx.user || {};
  const key = String(acct.id || acct.domain || 'unknown');
  const now = new Date().toISOString();
  let isNew = false, rec = null;
  try {
    const store = $getWorkflowStaticData('global');
    store.fub_installs = store.fub_installs || {};
    if (!store.fub_installs[key]) {
      isNew = true;
      store.fub_installs[key] = { account_id: acct.id || null, domain: String(acct.domain || ''), owner_name: String(owner.name || ''),
                                  owner_email: String(owner.email || ''), first_seen: now, users: {} };
    }
    rec = store.fub_installs[key];
    rec.last_seen = now;
    if (user.email && Object.keys(rec.users).length < 50) rec.users[String(user.email)] = String(user.name || '');
  } catch (e) { rec = { account_id: acct.id || null, domain: String(acct.domain || ''), owner_name: String(owner.name || ''), owner_email: String(owner.email || ''), first_seen: now, users: {} }; }
  return [{ json: {
    route: isNew ? 'capture_new' : 'respond',
    status: 200,
    response: { state: 'account_not_found', account_id: acct.id || null,
                prefill: { name: String(user.name || owner.name || ''), email: String(user.email || owner.email || '') },
                preview: { lead_first_name: String((ctx.person && ctx.person.firstName) || '').slice(0, 40),
                           agent_first_name: String(user.name || owner.name || '').split(' ')[0].slice(0, 40) } },
    install: rec,
    user: { name: String(user.name || ''), email: String(user.email || '') },
  } }];
}

const person = ctx.person || null;
if (!person) return respond(200, { state: 'person_not_found' });

const phones = Array.isArray(person.phones) ? person.phones : [];
const pick = phones.find(p => Number(p.isPrimary) === 1) || phones[0];
let digits = String((pick && (pick.normalized || pick.value)) || '').replace(/\D/g, '');
if (digits.length === 11 && digits.startsWith('1')) digits = digits.slice(1);
if (digits.length !== 10) return respond(200, { state: 'person_not_found', reason: 'no_phone' });

return [{ json: {
  route: 'lookup',
  phone: '+1' + digits,
  first_name: String(person.firstName || ''),
  client,
  month: new Date().toISOString().slice(0, 7),
} }];

// ============================================================
// Starling AI — FUB Embedded App: build the panel response
// ============================================================
const r = $('Verify & Route').first().json;
const client = r.client || {};

const rowsOf = (name) => { try { return $(name).all().map(i => i.json || {}); } catch (e) { return []; } };
const chatRows = rowsOf('Get Chat History').filter(j => j && j.session_id && j.error === undefined);
const optRows  = rowsOf('Get Opt-Out').filter(j => j && j.session_id && j.error === undefined);
const useRows  = rowsOf('Get Monthly Usage').filter(j => j && j.month !== undefined && j.error === undefined);

function textOf(m) {
  if (m == null) return { kind: '', text: '' };
  if (typeof m === 'object') return { kind: String(m.type || ''), text: String(m.content || m.text || '') };
  const s = String(m);
  if (s.trim().startsWith('{')) { try { const o = JSON.parse(s); return { kind: String(o.type || ''), text: String(o.content || o.text || '') }; } catch (e) {} }
  return { kind: '', text: s };
}

const msgs = [];
for (const row of chatRows) {
  const { kind, text } = textOf(row.message);
  const t = text.trim(); if (!t) continue;
  let from = null, clean = t;
  if (/^starling ai \/\s*new lead:/i.test(t)) continue;            // internal lead-intake log (has contact details)
  if (/^meeting created \/\s*/i.test(t)) { from = 'meeting'; clean = 'Meeting booked ' + t.replace(/^meeting created \/\s*/i, '').trim(); }
  else if (/^starling ai\s*\/\s*/i.test(t)) { from = 'ai'; clean = t.replace(/^starling ai\s*\/\s*/i, ''); }
  else if (/^client\s*\/\s*/i.test(t)) { from = 'lead'; clean = t.replace(/^client\s*\/\s*/i, ''); }
  else if (kind === 'ai') from = 'ai';
  else if (kind === 'human') from = 'lead';
  else continue;
  msgs.push({ from, text: clean.trim().slice(0, 500), at: row.created_at || null });
}
msgs.sort((a, b) => String(a.at || '').localeCompare(String(b.at || '')));

const optedOut = optRows.length > 0;
const hasMeeting = msgs.some(m => m.from === 'meeting');
const hasAi = msgs.some(m => m.from === 'ai');
const status = optedOut ? 'opted_out' : hasMeeting ? 'meeting_booked' : hasAi ? 'active' : 'not_contacted';

const useRow = useRows.find(u => String(u.month) === r.month);
const used = useRow ? Number(useRow.total_billable_executions) : null;
const usage = Number.isFinite(used) ? { used, limit: Number(client.monthly_limit) || null } : null;

return [{ json: { status: 200, response: {
  state: 'working',
  client_name: client.name || '',
  lead_first_name: r.first_name || '',
  status,
  last_activity: msgs.length ? msgs[msgs.length - 1].at : null,
  messages: msgs.slice(-8),
  usage,
} } }];
